/**
 * 터미널 제목에서 작업 이름을 뽑는다.
 *
 * - `claude`: 앞에 붙는 스피너 글리프(`✳`, `⠂` …)를 떼고 남은 제목. 기본 제목("Claude Code")은 작업이 아니다.
 * - `pi`: `π - <세션 이름> - <폴더>` 꼴에서 가운데 세션 이름. 세션 이름 자체에 ` - `가 들어갈 수 있다.
 */
import type { Harness } from "$lib/projects/harness.js";

/** 하네스가 스스로 붙이는 기본 제목. 작업 이름으로 보지 않는다. */
const DEFAULT_TITLES = new Set(["claude", "claude code", "pi", "pi-bolt"]);

/** 제목 앞머리의 스피너·장식 글리프(문자·숫자가 아닌 문자)를 걷어낸다. */
function stripLeadingGlyphs(title: string): string {
	return title.replace(/^[^\p{L}\p{N}]+/u, "").trim();
}

function isDefaultTitle(title: string): boolean {
	return DEFAULT_TITLES.has(title.trim().toLowerCase());
}

function claudeTitle(title: string): string | null {
	const rest = stripLeadingGlyphs(title);
	return !rest || isDefaultTitle(rest) ? null : rest;
}

function piTitle(title: string): string | null {
	const parts = stripLeadingGlyphs(title)
		.split(" - ")
		.map((part) => part.trim());
	// 앱 이름과 폴더가 있어야 세션 이름이 그 사이에 있다.
	if (parts.length < 3) return null;
	const name = parts.slice(1, -1).join(" - ").trim();
	return !name || isDefaultTitle(name) ? null : name;
}

export function taskTitle(harness: Harness, title: string): string | null {
	if (!title) return null;
	return harness === "pi" ? piTitle(title) : claudeTitle(title);
}

